python3 -c "
import os, re

# Find unwrap calls in non-test code
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            lines = fh.readlines()
        in_test = False
        cfg_test_depth = 0
        for i, line in enumerate(lines):
            if '#[cfg(test)]' in line:
                in_test = True
                cfg_test_depth = 0
            if in_test:
                cfg_test_depth += line.count('{') - line.count('}')
                if cfg_test_depth <= 0 and i > 0:
                    in_test = False
            if not in_test and '.unwrap()' in line:
                print(f'{path}:{i+1}: {line.rstrip()}')
"

